/* Numera Academy — Página Jogos: Calculândia e Quem Divergiu?, com o progresso salvo de cada um.
   Parte da interface (antes, app.js). Os arquivos de js/site e js/paginas são scripts clássicos que
   compartilham as mesmas variáveis; a ordem de carregamento está no index.html. */
'use strict';
/* ---------- Jogos (v12): no lugar da Arena ----------
   Calculândia (aventura 3D, em jogos/calculandia) e Quem Divergiu? (jogo de sala, em jogos/quem-divergiu).
   Os dois salvam no próprio navegador; aqui só lemos o resumo, com cada campo conferido. */
const readJSON=key=>{try{const raw=localStorage.getItem(key);if(!raw)return null;const d=JSON.parse(raw);return d&&typeof d==='object'?d:null;}catch(_){return null;}};
function calcSummary(){const d=readJSON('calculandia-save-v1');if(!d)return null;const ph=d.phases&&typeof d.phases==='object'?d.phases:{};let stars=0,wins=0;for(const [k,v] of Object.entries(ph)){if(!v||typeof v!=='object')continue;if(Number(v.wins)>0)wins++;if(/-[FMD]$/.test(k))stars+=Math.max(0,Math.min(3,Math.floor(Number(v.stars)||0)));}const roots=d.roots&&typeof d.roots==='object'?Object.keys(d.roots).length:0;return {stars:Math.min(189,stars),roots:Math.min(40,roots),wins:Math.min(69,wins)};}
function qdSummary(){const d=readJSON('numera-quem-divergiu-v1'),st=d&&d.stats&&typeof d.stats==='object'?d.stats:{},n=v=>Math.max(0,Math.min(1e6,Math.floor(Number(v)||0)));return {games:n(st.games),rounds:n(st.rounds)};}
function jogos(){const cs=calcSummary(),qd=qdSummary();
 const card=(o)=>`<article class="game-card card ${o.cls}" aria-labelledby="${o.id}-t"><a class="game-cover" href="${o.href}" tabindex="-1" aria-hidden="true"><img src="${o.img}" alt="" width="1200" height="675" loading="lazy" decoding="async"></a><div class="game-body"><span class="eyebrow">${o.eyebrow}</span><h2 class="display" id="${o.id}-t">${o.title}</h2><p>${o.text}</p><ul class="game-facts">${o.facts.map(([b,t])=>`<li><b>${b}</b><span>${t}</span></li>`).join('')}</ul><p class="game-progress">${o.progress}</p><div class="row-actions"><a class="btn primary" href="${o.href}">${o.cta} ${icon('arrow')}</a></div><p class="fine">${o.note}</p></div></article>`;
 return `<div class="wrap page-body">${heading('Jogos','Aprenda jogando','Os mesmos métodos das trilhas em três jogos: uma aventura para jogar sozinho, um jogo de sala para a turma inteira, no telão, e o Relâmpago, com as perguntas rápidas das listas.')}<div class="games">
 ${card({id:'calc',cls:'game-calc',href:'jogos/calculandia/index.html',img:'jogos/capas/calculandia.webp',eyebrow:'Aventura 3D · para jogar sozinho',title:'Calculândia — Caçadores de Raízes',text:'Explore uma ilha em 3D, converse com os bichos guias e resolva fases táticas: arraste o intervalo da Bisseção, mire a tangente do Newton, prepare a eliminação de uma matriz. Cada região termina num chefão, e a Usina junta tudo.',facts:[['63','fases'],['21','métodos'],['5','chefões e a Usina']],progress:cs?`⭐ ${cs.stars} de 189 estrelas · ${cs.wins} ${cs.wins===1?'fase vencida':'fases vencidas'} · ${cs.roots} de 40 Raízes Fugitivas`:'Ainda não começou. O progresso fica salvo neste navegador.',cta:'Jogar a Calculândia',note:'Teclado e mouse, ou toque. Precisa de WebGL; num computador mais fraco, use Menu → Opções → Qualidade leve.'})}
 ${card({id:'qd',cls:'game-qd',href:'jogos/quem-divergiu/index.html',img:'jogos/capas/quem-divergiu.webp',eyebrow:'Jogo de sala · para o telão',title:'Quem Divergiu?',text:'A professora projeta uma pergunta da matéria com resposta numérica. Cada aluno faz um palpite em segredo, a turma vota em quem deve ter divergido, e a reta numérica revela a resposta com as faixas de tolerância. Quem chega mais perto converge; quem erra feio leva o carimbo.',facts:[['2 a 12','jogadores ou times'],['3','faixas de tolerância'],['0','instalação']],progress:qd.games?`${qd.games} ${qd.games===1?'partida jogada':'partidas jogadas'} neste navegador · ${qd.rounds} rodadas`:'Nenhuma partida ainda. Dá para jogar com palpites no papel ou passando o aparelho.',cta:'Abrir no telão',note:'Funciona offline num computador só, ligado ao projetor. As respostas são calculadas pelo motor do Numera, com o passo a passo para a professora explicar.'})}
 ${rlCartaoJogos()}
 </div><section class="card games-howto" aria-labelledby="howto-t"><h2 id="howto-t">Como jogar o Quem Divergiu? em sala</h2><ol><li><b>Monte a turma.</b> Até 12 nomes, ou times (Fileira 1, Fileira 2…). Escolha os métodos que a turma já viu e o número de rodadas.</li><li><b>Palpite em segredo.</b> No modo telão, cada um escreve o número no caderno; no modo passa o aparelho, cada um digita escondido.</li><li><b>Vote em quem divergiu.</b> Cada jogador aponta quem ele acha que errou mais. Os votos aparecem juntos.</li><li><b>Revele.</b> A resposta cai na reta numérica com as faixas de 1%, 5% e 20%. Pontos por proximidade, por voto certeiro e para quem foi votado sem ter errado mais.</li></ol></section></div>`;}

